//! Start-page backgrounds the user uploaded, one data URL per file in the profile's wallpapers
//! folder (`Paths::wallpapers`).

use std::path::PathBuf;

use crate::app::command::CmdResult;
use crate::host::paths;

/// Largest uploaded background accepted (as a data URL). The UI downscales images first.
pub const WALLPAPER_MAX_BYTES: usize = 24 * 1024 * 1024;

/// Ids of uploaded backgrounds are generated by the UI: short, lowercase letters, digits and
/// dashes, so they can never name a path outside the wallpapers folder.
pub fn valid_wallpaper_id(id: &str) -> bool {
    !id.is_empty() && id.len() <= 40 && id.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
}

/// Only raster images encoded as base64 data URLs are stored (no SVG: it can carry script).
pub fn valid_wallpaper_data(data: &str) -> bool {
    data.len() <= WALLPAPER_MAX_BYTES
        && ["data:image/jpeg;base64,", "data:image/png;base64,", "data:image/webp;base64,"]
            .iter()
            .any(|p| data.starts_with(p))
}

pub(crate) fn wallpaper_file(id: &str) -> CmdResult<PathBuf> {
    if !valid_wallpaper_id(id) {
        return Err("invalid background id".into());
    }
    Ok(paths().wallpapers().join(format!("{id}.txt")))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn wallpaper_ids_and_data_are_checked() {
        assert!(valid_wallpaper_id("w-lq3k9z-4f2a"));
        for bad in ["", "../settings", "a/b", "a\\b", "UPPER", "x.txt", &"a".repeat(41)] {
            assert!(!valid_wallpaper_id(bad), "{bad}");
        }
        assert!(valid_wallpaper_data("data:image/jpeg;base64,AAAA"));
        assert!(valid_wallpaper_data("data:image/png;base64,AAAA"));
        assert!(!valid_wallpaper_data("data:image/svg+xml,<svg onload=alert(1)>"));
        assert!(!valid_wallpaper_data("https://example.com/a.jpg"));
    }
}
